"""Install the daily bookmarks sync as a systemd user timer.

Writes x-bookmarks-sync.{service,timer} into ~/.config/systemd/user with this
checkout's path and uv's location filled in, reloads systemd, and enables the
timer. Idempotent: re-running rewrites the units and leaves the timer enabled.

Usage:
    uv run python -m x_api.timer install
"""

import shutil
import subprocess
import sys
from pathlib import Path

UNIT_DIR = Path.home() / ".config" / "systemd" / "user"
REPO_DIR = Path(__file__).resolve().parents[2]
NAME = "x-bookmarks-sync"

SERVICE = """\
# Generated by `python -m x_api.timer install` from {repo}. Edits are overwritten.
[Unit]
Description=Append new X bookmarks to the bookmarks inbox note
Documentation=file:{repo}/README.md
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
Environment=PATH={uv_dir}:/usr/local/bin:/usr/bin
ExecStart={uv} run --directory {repo} python -m x_api.sync_bookmarks
StandardOutput=journal
StandardError=journal
Nice=10
"""

TIMER = """\
# Generated by `python -m x_api.timer install` from {repo}. Edits are overwritten.
[Unit]
Description=Daily X bookmarks sync
Documentation=file:{repo}/README.md

[Timer]
# Bookmarks are read-later material, and each run is billed per post returned
# (~10 reads per account when nothing is new), so once a day is plenty.
OnCalendar=*-*-* 07:00:00
RandomizedDelaySec=15min
# Catch up after the machine was off; the sync dedupes, so a late run is harmless.
Persistent=true

[Install]
WantedBy=timers.target
"""


def install() -> None:
    uv = shutil.which("uv")
    if not uv:
        sys.exit("uv not found on PATH")
    fields = {"repo": REPO_DIR, "uv": uv, "uv_dir": Path(uv).parent}

    UNIT_DIR.mkdir(parents=True, exist_ok=True)
    for suffix, template in ((".service", SERVICE), (".timer", TIMER)):
        path = UNIT_DIR / f"{NAME}{suffix}"
        # Replace a symlink rather than writing through it into someone else's file.
        if path.is_symlink():
            path.unlink()
        path.write_text(template.format(**fields))
        print(f"wrote {path}", flush=True)

    subprocess.run(["systemctl", "--user", "daemon-reload"], check=True)
    subprocess.run(["systemctl", "--user", "enable", "--now", f"{NAME}.timer"], check=True)
    subprocess.run(["systemctl", "--user", "list-timers", f"{NAME}.timer", "--no-pager"], check=True)


def main() -> None:
    if sys.argv[1:] == ["install"]:
        install()
    else:
        print(__doc__)


if __name__ == "__main__":
    main()
